# -*- coding: utf-8 -*-
R={
"D01":"كان رسول الله ﷺ لا يضحك إلا تبسّمًا.",
"D02":"كان رسول الله ﷺ لا يضحك إلا تبسّمًا، وكان إذا نظرتَ إليه قلتَ: أكحلُ العينين، وما هو بأكحل.",
"D04":"كان رسول الله ﷺ يحدّث أصحابه عن آخر أهل النار خروجًا منها، حتى ضحك ﷺ فبدت نواجذه.",
"D09":"كان رسول الله ﷺ إذا مرّ ببعيرٍ قد لصق ظهره ببطنه من الهزال والجوع قال: «اتقوا الله في هذه البهائم العجماء».",
"D13":"كان رسول الله ﷺ يتبسّم من ظرافة أصحابه: أكل صهيب التمر وبه رمد، وقال إنه يأكل من الجانب الآخر، فتبسّم ﷺ.",
"D14":"كان رسول الله ﷺ يتبسّم من مواقف أصحابه: رأى مُحرمًا يضرب بعيره الذي أضلّه، فقال «انظروا إلى هذا المُحرم ما يصنع!» وتبسّم.",
"D15":"كان رسول الله ﷺ يضحك من عفوية أصحابه ثم يعلّمهم برفق: تمرّغ عمّار في التراب ليتطهّر، فضحك ﷺ وعلّمه.",
"D16":"كان رسول الله ﷺ يتبسّم ضاحكًا من شدّة شبه الابن بأبيه، حين أقسم رجل أنه ابنه.",
"D17":"كان رسول الله ﷺ لا يحجب جريرًا عنه منذ أسلم، ولا يراه إلا تبسّم في وجهه.",
"D18":"كان رسول الله ﷺ يضحك حتى تبدو نواجذه من جواب عائشة الظريف عن فرس لها جناحان: «ألم تسمع أن لسليمان خيلًا لها أجنحة؟»",
"D19":"كان رسول الله ﷺ يضحك من هيبة عمر: ابتدرت النسوة الحجاب لمّا سمعن صوته، فعجب ﷺ وتبسّم.",
"D20":"كان رسول الله ﷺ يتبسّم لحبّ أصحابه له: جمعت أم سُليم عرقه الطيب لتجعله في طيبها، فأقرّها ﷺ.",
"D21":"كان رسول الله ﷺ من أحسن الناس خلقًا، حتى إنه أمسك بقفا أنس وهو يلعب مع الصبيان ويضحك: «يا أُنيس، أذهبتَ حيث أمرتك؟»",
"D22":"كان رسول الله ﷺ يُخرج لسانه للحسن بن علي، فيرى الصبيُّ حُمرة لسانه فيُسرع إليه فرحًا.",
"D23":"كان رسول الله ﷺ يداعب الصغار؛ ومن ذلك أن محمود بن الربيع تذكّر وهو ابن خمس سنين أن النبي ﷺ مجّ في وجهه مَجّةً من ماء.",
"D24":"كان رسول الله ﷺ يمازح الصغار: أُهدي إليه خميصة ذات أعلام، فألبسها أمّ خالد الصغيرة، وقال لها: «سَنَهْ، سَنَهْ» أي: حَسَن حَسَن.",
"D25":"كان رسول الله ﷺ يصلّي بالناس، فجاء الحسن أو الحسين فركب على ظهره وهو ساجد، فأطال السجود حتى لا يُعجَل الصغير عن لعبه، ثم بيّن ذلك للناس.",
"D26":"كان رسول الله ﷺ إذا سُرّ استنار وجهه حتى كأنه قطعة قمر، وكنّا نعرف ذلك منه.",
"D27":"كان رسول الله ﷺ إذا فرح لم يتمالك نفسه؛ فلما جاء عكرمة بن أبي جهل مسلمًا، وثب إليه فرحًا حتى ما ارتدى رداءه.",
"D28":"كان رسول الله ﷺ يفرح بحبّ أهله له فرحًا شديدًا: لما خيّر نساءه فاخترنه، فرح، وقالت عائشة: ثم فعل أزواجه مثل ما فعلتُ.",
"D29":"كان رسول الله ﷺ يبرق وجهه من الفرح، فلما جاءه كعب بن مالك بعد أن تاب الله عليه قال له: «أبشر بخير يوم مرّ عليك منذ ولدتك أمك».",
"D30":"كان رسول الله ﷺ يحفظ الودّ لخديجة بعد وفاتها، فلما سمع استئذان أختها هالة ارتاع للصوت لشبهه بصوت خديجة، وقال: «اللهم هالة بنت خويلد».",
"D31":"كان رسول الله ﷺ إذا جاءه أمر يُسرّه، أو بُشّر به، خرّ ساجدًا شكرًا لله.",
"D32":"كان رسول الله ﷺ يتألم لفقر أصحابه؛ فلما رأى قومًا حفاة عراة تغيّر وجهه، ثم تصدّق الناس حتى رأيتُ وجهه يتهلّل كأنه مُذهَبة.",
"E01":"كان رسول الله ﷺ يقول عن أبي بكر وعمر: «هذان السمع والبصر».",
"E02":"كان رسول الله ﷺ إذا دخلت عليه ابنته فاطمة قام إليها فقبّلها وأجلسها في مجلسه، وكانت هي إذا دخل عليها فعلت به مثل ذلك.",
"E03":"كان رسول الله ﷺ يقول عن ابنته فاطمة: «إنما فاطمة بَضعة مني، يؤذيني ما آذاها».",
"E04":"كان رسول الله ﷺ يقول عن حفيديه الحسن والحسين: «هما ريحانتاي من الدنيا».",
"E05":"كان رسول الله ﷺ يأخذ حفيديه الحسن والحسين ويقول: «اللهم إني أحبهما فأحبهما، وأحبّ من يحبهما».",
"E06":"كان رسول الله ﷺ إذا ذبح الشاة أرسل من لحمها إلى صديقات خديجة، فإذا عاتبته عائشة قال: «إني قد رُزقتُ حبّها».",
"E07":"كان رسول الله ﷺ يقول لأم سلمة حين آذت عائشة: «لا تؤذيني في عائشة، فإنه واللهِ ما نزل عليّ الوحي وأنا في لحاف امرأة منكنّ غيرها».",
"F01":"كان رسول الله ﷺ يأخذ بيد معاذ بن جبل فيقول: «والله إني لأحبك»، ثم يوصيه بدعاء يقوله دبر كل صلاة.",
"F02":"كان رسول الله ﷺ يوم الأحزاب يطلب من يأتيه بخبر القوم، فانتدب الزبير، فقال ﷺ: «إن لكل نبي حواريًّا، وحواريّي الزبير».",
"F03":"كان رسول الله ﷺ يحبّ عمّار بن ياسر وعبد الله بن مسعود حتى شهد عمرو بن العاص عند موته أن النبي ﷺ فارق الدنيا وهو يحبهما.",
"F04":"كان رسول الله ﷺ يحبّ أسامة حبًّا يُرى حتى إنه أراد أن ينحّي مخاط أنفه بنفسه، فقالت عائشة: دعني أنا، فقال ﷺ: «يا عائشة أحبّيه فإني أحبّه».",
"F05":"كان رسول الله ﷺ إذا رأى نساء الأنصار وصبيانهم مقبلين قام ممتنًّا فقال ثلاثًا: «اللهم أنتم من أحبّ الناس إليّ».",
"F06":"كان رسول الله ﷺ يلاطف الصغار، فلما غنّت له جاريات: «نحن جوارٍ من بني النجار، يا حبّذا محمد من جار» قال لهن: «يعلم الله إني لأحبكنّ».",
"G01":"كان رسول الله ﷺ يصلّي، ولصدره أزيزٌ كأزيز المِرْجَل من البكاء.",
"G02":"كان رسول الله ﷺ يخطب في أصحابه خطبة ما سمعوا مثلها، فيقول: «لو تعلمون ما أعلم لضحكتم قليلًا ولبكيتم كثيرًا»، فغطّى أصحابه وجوههم ولهم خنين.",
"G03":"كان رسول الله ﷺ يقوم من الليل حتى تتفطّر قدماه، فقالت عائشة: لِمَ تصنع هذا وقد غُفر لك ما تقدّم وما تأخّر؟ فقال: «أفلا أكون عبدًا شكورًا؟»",
"G04":"كان رسول الله ﷺ يطلب من ابن مسعود أن يقرأ عليه القرآن، فلما بلغ آية الشهادة قال: «حسبك الآن»، وعيناه تذرفان.",
"G05":"كان رسول الله ﷺ إذا زار قبر أمه بكى وأبكى من حوله، وقال: «فزوروا القبور فإنها تذكّر الموت».",
"G06":"كان رسول الله ﷺ يبكي رحمةً بمرضاه؛ عاد سعد بن عبادة فبكى، وقال: «إن الله لا يعذّب بدمع العين ولا بحزن القلب، ولكن يرحم بهذا» وأشار إلى لسانه.",
"G07":"كان رسول الله ﷺ يُخبر الناس بموت أحبّته، فنعى زيدًا وجعفرًا وابن رواحة قبل أن يأتيهم خبرهم، وعيناه تذرفان.",
"H01":"كان رسول الله ﷺ يقول لأصحابه: «إنما أنا لكم بمنزلة الوالد، أعلّمكم».",
"H03":"كان رسول الله ﷺ يقول في خطبته في حجة الوداع: «وقد تركتُ فيكم ما لن تضلّوا بعده إن اعتصمتم به: كتاب الله».",
"J01":"كان رسول الله ﷺ ليس بالطويل البائن ولا بالقصير، ولا بالأبيض الأمهق ولا بالآدم، ولا بالجعد القَطِط ولا بالسَّبِط.",
"J02":"كان رسول الله ﷺ ألين الناس كفًّا؛ قال أنس: ما مسستُ حريرًا ولا ديباجًا ألين من كفّ النبي ﷺ، ولا شممتُ رائحة قط أطيب من رائحة النبي ﷺ.",
"J03":"كان رسول الله ﷺ إذا مشى تقلّع كأنما ينحطّ من صبَب، وإذا التفت التفت جميعًا.",
"J04":"كان رسول الله ﷺ يتكلم بجوامع الكلم، فصلًا لا فضول فيه ولا تقصير.",
"K01":"كان رسول الله ﷺ لا يذمّ أحدًا ولا يعيّره، ولا يطلب عورته.",
"K02":"كان رسول الله ﷺ إذا تكلم أطرق جلساؤه كأنما على رؤوسهم الطير.",
"K03":"كان رسول الله ﷺ يقسم قسمًا فقال له رجل: اعدل يا رسول الله! فلم يغضب وقال: «ويلك، ومن يعدل إذا لم أعدل؟ قد خبتَ وخسرتَ إن لم أكن أعدل».",
"K04":"كان رسول الله ﷺ بين كتفيه خاتم النبوة، كأنه بيضة حمامة.",
"K05":"كان رسول الله ﷺ يمسح رأس طفل مريض ويدعو له بالبركة، فنظر الطفل إلى خاتم النبوة بين كتفيه، فإذا هو مثل زرّ الحَجَلة.",
"K06":"كان شعر رسول الله ﷺ يبلغ شحمة أذنيه، ويضرب منكبيه.",
"K07":"كان رسول الله ﷺ لم يبلغ من الشيب إلا قليلًا، لم يكن في رأسه ولحيته عشرون شعرة بيضاء.",
"K08":"كان رسول الله ﷺ يُقال له: قد شِبتَ! فيقول: «شيّبتني هود والواقعة والمرسلات وعمّ يتساءلون وإذا الشمس كوّرت».",
"L01":"كان رسول الله ﷺ يحثّ على لبس البياض فيقول: «البسوا من ثيابكم البياض، فإنها من خير ثيابكم».",
"L02":"كان رسول الله ﷺ ينهى عن المشي في نعل واحدة ويقول: «لا يمشِ أحدكم في نعل واحدة، ليُحفِهما جميعًا أو ليُنعلهما جميعًا».",
"L03":"كان رسول الله ﷺ يلبس خاتمه في يمينه، وكان نقشه: «محمد رسول الله».",
"L04":"كان رسول الله ﷺ يوصي بتشمير الإزار فيقول: «ارفع إزارك إلى نصف الساق، وإياك وإسبال الإزار فإنه من المَخيلة».",
"M01":"كان وجه رسول الله ﷺ مثل القمر؛ سُئل البراء: أكان وجهه مثل السيف؟ قال: لا، بل مثل القمر.",
"M02":"كان رسول الله ﷺ أبيض كأنما صِيغ من فضة.",
"M03":"كان رسول الله ﷺ أبيض مليحًا مُقصَّدًا — قال أبو الطفيل، وقد كان آخر من رآه من الصحابة.",
"M04":"كان رسول الله ﷺ لا يشبهه أحد؛ قال علي: لم أرَ قبله ولا بعده مثله ﷺ.",
"N01":"كان رسول الله ﷺ مربوعًا، بعيد ما بين المنكبين، له جُمّة تضرب شحمة أذنيه، عليه حلّة حمراء، ما رأيت شيئًا قط أحسن منه ﷺ.",
"N02":"كان رسول الله ﷺ يسدل شعره موافقةً لأهل الكتاب فيما لم يؤمر فيه بشيء، ثم فرق رأسه.",
"N03":"كان رسول الله ﷺ يُدني رأسه إلى عائشة فتُرجّله وهي حائض.",
"N04":"كان رسول الله ﷺ يعجبه التيمّن في تنعّله وترجّله وطهوره وفي شأنه كله.",
"N05":"كان رسول الله ﷺ بشرًا من البشر، يفلي ثوبه ويحلب شاته ويخدم نفسه.",
"N06":"كان رسول الله ﷺ يحجّ على رحلٍ رثّ وقطيفة تساوي أربعة دراهم، ويقول: «اللهم حجة لا رياء فيها ولا سمعة».",
"N07":"كان رسول الله ﷺ أحبّ الناس إلى أصحابه، ومع ذلك كانوا إذا رأوه لم يقوموا له، لما يعلمون من كراهيته لذلك.",
"P01":"كان رسول الله ﷺ لا يعنّف خادمه؛ قال أنس: خدمتُ النبي ﷺ عشر سنين، فما قال لي «أُفٍّ» ولا «لِمَ صنعتَ» ولا «ألا صنعتَ».",
"P02":"كان رسول الله ﷺ يقبّل الحسن بن علي، فقال الأقرع بن حابس: إن لي عشرة من الولد ما قبّلتُ منهم أحدًا، فنظر إليه ﷺ وقال: «من لا يَرحم لا يُرحم».",
"P03":"كان رسول الله ﷺ يقوم إلى الصلاة يريد أن يطوّل فيها، فيسمع بكاء الصبي فيتجوّز في صلاته كراهية أن يشقّ على أمه.",
"P04":"كان رسول الله ﷺ يصلّي وهو حامل أُمامة بنت زينب، فإذا سجد وضعها وإذا قام حملها.",
"P05":"كان رسول الله ﷺ يخالط الناس حتى يقول لأخٍ صغير لأنس: «يا أبا عُمير، ما فعل النُّغَير؟»",
"P06":"كان رسول الله ﷺ لا يُسأل شيئًا فيقول «لا»؛ قال جابر: ما سُئل النبي ﷺ عن شيء قط فقال: لا.",
"P07":"كان رسول الله ﷺ يعود غلامًا يهوديًّا كان يخدمه، فقعد عند رأسه وعرض عليه الإسلام فأسلم، فخرج ﷺ وهو يقول: «الحمد لله الذي أنقذه بي من النار».",
"P08":"كان رسول الله ﷺ يترك الأَمَة من إماء المدينة تأخذ بيده فتنطلق به حيث شاءت، ما ينزع يده من يدها حتى تقضي حاجتها.",
"P10":"كان رسول الله ﷺ يشتاق إلى من يأتي بعده من أمته: «وددتُ أنّا قد رأينا إخواننا»، قالوا: أوَلسنا إخوانك؟ قال: «أنتم أصحابي، وإخواننا الذين لم يأتوا بعد».",
"Q02":"كان رسول الله ﷺ يرجو الخير لقومه وقد آذوه؛ عرض عليه ملَك الجبال أن يُطبق عليهم الأخشبين، فقال: «بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده».",
"Q03":"كان رسول الله ﷺ يفرح بحبّ أصحابه له؛ قال له رجل: ما أعددتُ للساعة إلا حبّ الله ورسوله، فقال: «أنت مع من أحببت». قال أنس: فما فرحنا بشيء فرحنا بذلك.",
"Q04":"كان رسول الله ﷺ يدّخر لأمته أعظم ما يملك؛ فقال: «لكل نبي دعوة مستجابة، فتعجّل كل نبي دعوته، وإني اختبأتُ دعوتي شفاعةً لأمتي يوم القيامة».",
"Q06":"كان رسول الله ﷺ إذا خطب احمرّت عينه وعلا صوته واشتد غضبه، ويقول: «من ترك دينًا أو ضياعًا فإليّ وعليّ».",
"S01":"كان رسول الله ﷺ أشجع الناس؛ فزع أهل المدينة ليلةً فسبقهم نحو الصوت، وعاد يقول: «لم تُراعوا، لم تُراعوا».",
"S02":"كان رسول الله ﷺ ما خُيّر بين أمرين إلا أخذ أيسرهما ما لم يكن إثمًا.",
"S03":"كان رسول الله ﷺ ما ضرب شيئًا قط بيده، لا امرأة ولا خادمًا، إلا أن يجاهد في سبيل الله.",
"S04":"كان رسول الله ﷺ إذا بال أعرابي في المسجد ونهره الصحابة قال: «دعوه وأهريقوا على بوله ذَنوبًا من ماء، فإنما بُعثتم ميسّرين ولم تُبعثوا معسّرين».",
"S05":"كان رسول الله ﷺ أحسن الناس تعليمًا؛ قال معاوية بن الحكم: فبأبي هو وأمي، ما رأيتُ معلّمًا قبله ولا بعده أحسن تعليمًا منه، فواللهِ ما كهرني ولا ضربني ولا شتمني.",
"S06":"كان رسول الله ﷺ يسابق أهله؛ قالت عائشة: سابقتُه فسبقتُه، فلما حملتُ اللحم سابقتُه فسبقني فقال: «هذه بتلك السّبقة».",
"S07":"كان رسول الله ﷺ يقول: «خيركم خيركم لأهله، وأنا خيركم لأهلي».",
"T01":"كان رسول الله ﷺ يقول: «فوالذي نفسي بيده لا يؤمن أحدكم حتى أكون أحبّ إليه من والده وولده والناس أجمعين».",
"T02":"كان رسول الله ﷺ يريد أن يكون أحبّ إلى أصحابه من أنفسهم؛ قال لعمر: «حتى أكون أحبّ إليك من نفسك»، فقال عمر: الآن والله أنت أحبّ إليّ من نفسي، فقال ﷺ: «الآن يا عمر».",
}
